## ✅ Clean Solution in C
```c
/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     struct ListNode *next;
 * };
 */

struct ListNode* removeElements(struct ListNode* head, int val) {
    // Dummy node before head (handles edge cases easily)
    struct ListNode dummy;
    dummy.next = head;

    struct ListNode* prev = &dummy;
    struct ListNode* curr = head;

    while (curr != NULL) {
        if (curr->val == val) {
            // Skip current node
            prev->next = curr->next;
        } else {
            // Move prev only if not deleted
            prev = curr;
        }
        curr = curr->next;
    }

    return dummy.next;  // New head
}
```

---

